Route::get('/{path?}',function(\Illuminate\Http\Request $r){$path=$r->path();if(config('portal.kind')==='client'&&(str_starts_with($path,'owner')||str_starts_with($path,'gestion')))abort(404);if(config('portal.kind')==='owner'&&!in_array($path,['/','gestion','gestion/identidad'],true))abort(404);return response()->view('app')->header('Cache-Control','no-store, private');})->where('path','^(?!api(?:/|$)).*')->name('login');
